package com.vynedam.stockai.controller; import com.vynedam.stockai.dto.InventoryDtos.QualityRequest; import com.vynedam.stockai.model.QualityInspection; import com.vynedam.stockai.security.CurrentUser; import com.vynedam.stockai.service.QualityService; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/quality-inspections") public class QualityController {private final QualityService service;private final CurrentUser current;public QualityController(QualityService s,CurrentUser c){service=s;current=c;}@GetMapping List<QualityInspection>list(){return service.list();}@PostMapping@PreAuthorize("hasAnyRole('SUPER_ADMIN','QUALITY_MANAGER')")ResponseEntity<QualityInspection>create(@Valid@RequestBody QualityRequest r,Authentication a){return ResponseEntity.status(201).body(service.create(r,current.id(a)));}}
